function body(j) {
  const raw = j.text || j.textPlain || j.snippet || '';
  return String(raw)
    .replace(/(?:api[_-]?key|token|password|secret)\s*[:=]\s*\S+/gi, '[SECRET]')
    .replace(/\b(?:\d[ -]*?){13,19}\b/g, '[CARD]')
    .slice(0, 8000);
}

const items = $input.all().filter(i => i.json && (i.json.id || i.json.subject || i.json.Subject));
if (!items.length) {
  return [{ json: { id: '', threadId: '', from: '', subject: '', gmail_url: '', emailText: '(no emails in the last 24 hours)', _empty: true } }];
}

return items.map(({ json: j }) => {
  const id = j.id || '';
  const threadId = j.threadId || id;
  const from = j.from || j.From || '';
  const subject = j.subject || j.Subject || '(no subject)';
  return {
    json: {
      id,
      threadId,
      from,
      subject,
      snippet: String(j.snippet || '').slice(0, 280),
      gmail_url: threadId ? `https://mail.google.com/mail/u/0/#inbox/${threadId}` : '',
      emailText: `From: ${from}\nSubject: ${subject}\n\n${body(j)}`,
      _empty: false
    }
  };
});

