parameters.jsCode:
const rows = [];
for (const item of $input.all()) {
  const meta = $('Prep email text').all().find(p => {
    try { return p.json.emailText === item.json.emailText || p.json.id === (item.json.id || ''); }
    catch (e) { return false; }
  });
  const src = meta ? meta.json : {};
  const extracted = item.json.output || item.json;
  if (src._empty) continue;
  if (extracted.is_junk === true || String(extracted.category || '').toLowerCase() === 'junk') continue;
  const actions = Array.isArray(extracted.action_items) ? extracted.action_items : [];
  for (const a of actions) {
    if (!a || !a.task) continue;
    const slug = String(a.task).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().slice(0, 80);
    rows.push({
      json: {
        row_id: `${src.id || 'none'}::${slug}`,
        created_at: new Date().toISOString(),
        from: src.from || '',
        subject: src.subject || '',
        task: String(a.task).slice(0, 280),
        due: a.due || '',
        priority: a.priority || extracted.category || 'P1',
        status: 'open',
        gmail_url: src.gmail_url || '',
        category: extracted.category || 'P1',
        reason: extracted.reason || ''
      }
    });
  }
}
if (!rows.length) {
  return [{ json: { row_id: '', task: '', status: '', _empty: true } }];
}
return rows;

const tz = $('Config').first().json.timezone || 'Africa/Nairobi';
const now = DateTime.now().setZone(tz);
const today = now.toISODate();
const yourEmail = $('Config').first().json.yourEmail;

function safe(name) {
  try { return $(name).all().map(i => i.json).filter(j => j && !j._empty && Object.keys(j).length); }
  catch (e) { return []; }
}

const extractedRows = safe('Flatten extracted actions').filter(r => r.row_id && r.task);
const existing = safe('Sheet open actions').filter(a => String(a.status || 'open').toLowerCase() === 'open' && a.task);
const eventsRaw = safe('Calendar today').filter(e => e.summary || e.start);

const byId = {};
for (const a of existing) byId[a.row_id || a.task] = a;
for (const a of extractedRows) byId[a.row_id || a.task] = { ...byId[a.row_id || a.task], ...a };
const actions = Object.values(byId);

function scoreAction(a) {
  let s = 0;
  const due = String(a.due || '').slice(0, 10);
  const pri = String(a.priority || a.category || 'P2').toUpperCase();
  if (due && due < today) s += 80;
  if (pri === 'P0' || pri === '0') s += 60;
  if (due === today) s += 40;
  if (String(a.blocking).toLowerCase() === 'true') s += 25;
  return s;
}

function eventStart(e) { return e.start?.dateTime || e.start?.date || e.start || null; }

const events = eventsRaw.map(e => {
  const start = eventStart(e);
  let s = 0;
  if (start) {
    const t = DateTime.fromISO(String(start), { zone: tz });
    if (t.isValid) {
      const hours = t.diff(now, 'hours').hours;
      if (hours >= 0 && hours <= 2) s += 100;
    }
  }
  if (!String(e.description || '').trim()) s += 20;
  return {
    title: e.summary || '(no title)',
    start,
    end: e.end?.dateTime || e.end?.date || '',
    htmlLink: e.htmlLink || '',
    attendees: (e.attendees || []).map(a => a.email || a.displayName).filter(Boolean).slice(0, 8),
    score: s
  };
}).sort((a, b) => String(a.start).localeCompare(String(b.start)));

const actionsRanked = actions.map(a => ({ ...a, score: scoreAction(a) })).sort((a, b) => b.score - a.score);

const meetingPri = events.filter(e => e.score >= 100).map(e => ({
  task: `Attend / prep: ${e.title}`,
  due: today,
  priority: 'P0',
  score: e.score,
  kind: 'meeting'
}));

const top3 = [...actionsRanked.map(a => ({ ...a, kind: 'action' })), ...meetingPri]
  .sort((a, b) => (b.score || 0) - (a.score || 0))
  .slice(0, 3);

const junkCount = safe('Extractor').filter(x => {
  const o = x.output || x;
  return o.is_junk === true || String(o.category || '').toLowerCase() === 'junk';
}).length;

return [{
  json: {
    generated_at: now.toISO(),
    timezone: tz,
    yourEmail,
    date_human: now.toFormat('ccc dd LLL yyyy'),
    top_priorities: top3,
    open_actions: actionsRanked,
    overdue_count: actionsRanked.filter(a => String(a.due || '').slice(0, 10) && String(a.due).slice(0, 10) < today).length,
    calendar_today: events,
    meeting_count: events.length,
    junk_filtered: junkCount
  }
}];

const ranked = $('Rank + assemble context').first().json;
const inner = $json.html || $json.text || '';
const subject = `Priorities · ${ranked.date_human} · ${ranked.top_priorities.length} P0 · ${ranked.meeting_count} meetings`;
const html = `<!DOCTYPE html>
<html><body style="margin:0;padding:0;background:#111;font-family:Georgia,serif;">
<div style="max-width:640px;margin:24px auto;padding:32px 28px;background:#f7f1e8;color:#1a1a1a;border-radius:12px;">
<p style="margin:0 0 8px;font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:#6b4f2a;">Daily priorities</p>
${inner}
<p style="margin-top:28px;font-size:12px;color:#6b6b6b;">${ranked.generated_at} · ${ranked.timezone}<br>
Junk filtered: ${ranked.junk_filtered} · Overdue: ${ranked.overdue_count}</p>
</div></body></html>`;
return [{ json: { subject, html, to: ranked.yourEmail, text_preview: String($json.text || '').slice(0, 400) } }];

